import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Edit2, Trash2, Package, DollarSign, TrendingUp, AlertTriangle, Box } from 'lucide-react';
import toast from 'react-hot-toast';
import productService from '../../services/productService';
import DataTable from '../../components/datadisplay/DataTable';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import ProductFormModal from './ProductFormModal';
import ConfirmDialog from '../../components/feedback/ConfirmDialog.js';

const ProductManagement = () => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState(null);
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    const [filters, setFilters] = useState({
        search: '',
        page: 1,
        limit: 10
    });

    const queryClient = useQueryClient();

    const { data, isLoading } = useQuery({
        queryKey: ['products', filters],
        queryFn: () => productService.getAllProducts(filters)
    });

    const deleteMutation = useMutation({
        mutationFn: productService.deleteProduct,
        onSuccess: () => {
            toast.success('Product deleted successfully');
            queryClient.invalidateQueries(['products']);
            setDeleteConfirm(null);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to delete product');
        }
    });

    const stats = useMemo(() => {
        if (!data?.data) return null;
        const products = data.data;
        return {
            total: products.length,
            totalValue: products.reduce((sum, p) => sum + (p.price * p.quantity), 0),
            lowStock: products.filter(p => p.stockStatus.status === 'low_stock').length,
            outOfStock: products.filter(p => p.stockStatus.status === 'out_of_stock').length
        };
    }, [data]);

    const columns = [
        {
            key: 'name',
            label: 'Product',
            sortable: true,
            render: (row) => (
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden">
                        {row.imageUrl ? (
                            <img src={row.imageUrl} alt={row.name} className="h-full w-full object-cover" />
                        ) : (
                            <Package className="h-5 w-5 text-gray-400" />
                        )}
                    </div>
                    <div>
                        <p className="font-medium text-gray-900 dark:text-white">{row.name}</p>
                        <p className="text-xs text-gray-500 dark:text-gray-400">{row.sku}</p>
                    </div>
                </div>
            )
        },
        {
            key: 'price',
            label: 'Price',
            sortable: true,
            render: (row) => (
                <span className="font-medium">
                    ${parseFloat(row.price).toFixed(2)}
                </span>
            )
        },
        {
            key: 'quantity',
            label: 'Quantity',
            sortable: true,
            render: (row) => (
                <div className="flex items-center gap-2">
                    <span className="font-medium">{row.quantity}</span>
                    <StatusBadge
                        status={row.stockStatus.status}
                        label={row.stockStatus.label}
                    />
                </div>
            )
        },
        {
            key: 'actions',
            label: 'Actions',
            render: (row) => (
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => handleEdit(row)}
                        className="p-2 text-gray-400 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors"
                    >
                        <Edit2 className="h-4 w-4" />
                    </button>
                    <button
                        onClick={() => setDeleteConfirm(row)}
                        className="p-2 text-gray-400 hover:text-rose-600 dark:hover:text-rose-400 transition-colors"
                    >
                        <Trash2 className="h-4 w-4" />
                    </button>
                </div>
            )
        }
    ];

    const handleEdit = (product) => {
        setEditingProduct(product);
        setIsModalOpen(true);
    };

    const handleAdd = () => {
        setEditingProduct(null);
        setIsModalOpen(true);
    };

    const handlePageChange = (page) => {
        setFilters(prev => ({ ...prev, page }));
    };

    const handleSearch = (search) => {
        setFilters(prev => ({ ...prev, search, page: 1 }));
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                        Product Management
                    </h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        Manage your product inventory and catalog
                    </p>
                </div>

                <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={handleAdd}
                    className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors"
                >
                    <Plus className="h-5 w-5" />
                    Add Product
                </motion.button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard
                    icon={Box}
                    label="Total Products"
                    value={stats?.total || 0}
                    color="indigo"
                />
                <StatCard
                    icon={DollarSign}
                    label="Inventory Value"
                    value={`$${stats?.totalValue?.toFixed(2) || '0.00'}`}
                    color="teal"
                />
                <StatCard
                    icon={AlertTriangle}
                    label="Low Stock"
                    value={stats?.lowStock || 0}
                    color="amber"
                />
                <StatCard
                    icon={TrendingUp}
                    label="Out of Stock"
                    value={stats?.outOfStock || 0}
                    color="rose"
                />
            </div>

            {/* Product Table */}
            <DataTable
                columns={columns}
                data={data?.data || []}
                pagination={data?.pagination}
                onPageChange={handlePageChange}
                onSearch={handleSearch}
                loading={isLoading}
                emptyMessage="No products found. Add your first product!"
            />

            {/* Product Form Modal */}
            <ProductFormModal
                isOpen={isModalOpen}
                onClose={() => {
                    setIsModalOpen(false);
                    setEditingProduct(null);
                }}
                product={editingProduct}
                onSuccess={() => {
                    queryClient.invalidateQueries(['products']);
                    setIsModalOpen(false);
                    setEditingProduct(null);
                }}
            />

            {/* Delete Confirmation */}
            <ConfirmDialog
                isOpen={!!deleteConfirm}
                onClose={() => setDeleteConfirm(null)}
                onConfirm={() => deleteMutation.mutate(deleteConfirm.id)}
                title="Delete Product"
                message={`Are you sure you want to delete "${deleteConfirm?.name}"? This action cannot be undone.`}
                confirmText="Delete"
                variant="danger"
                loading={deleteMutation.isLoading}
            />
        </div>
    );
};

const StatCard = ({ icon: Icon, label, value, color }) => {
    const colorVariants = {
        indigo: 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400',
        teal: 'bg-teal-100 text-teal-600 dark:bg-teal-900/30 dark:text-teal-400',
        amber: 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400',
        rose: 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400',
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
        >
            <div className="flex items-center gap-4">
                <div className={`p-3 rounded-lg ${colorVariants[color]}`}>
                    <Icon className="h-6 w-6" />
                </div>
                <div>
                    <p className="text-sm text-gray-500 dark:text-gray-400">{label}</p>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">{value}</p>
                </div>
            </div>
        </motion.div>
    );
};

export default ProductManagement;
